index 7d362a9960ab..ebb692295df3 100644
--- a/sql/mysqld.cc
+++ b/sql/mysqld.cc
@@ -8952,7 +8952,7 @@ int mysqld_main(int argc, char **argv)
   {
     LogErr(ERROR_LEVEL, ER_MYINIT_FAILED);
     flush_error_log_messages();
-    return 1;
